INSERT INTO creative_style_presets (
    id, name, module, description, prompt_template, style_hint, tags,
    preview_url, source_name, source_url, enabled, sort_order
) VALUES
    ('moments-photo-diary', '朋友圈三格日记', 'TEXT_TO_IMAGE', '用环境、局部与动作组成可连续发布的生活记录。', '围绕同一时段和同一场景生成三格方形图：一格交代环境，一格记录触感细节，一格保留正在发生的小动作。共享自然光、统一镜头距离和低饱和色彩。', '不要把三格做成海报，不生成文字、标签、商标或水印；画面自然，有呼吸感。', ARRAY['朋友圈', '三格', '生活记录'], '/gallery-moments-solar-term.png', 'Gathered Scenes Zine', 'https://github.com/Zeejay0/gathered-scenes-zine-skill', TRUE, 50),
    ('quiet-architecture', '建筑光影散文', 'TEXT_TO_IMAGE', '用空间几何、真实材质和自然光表达安静的建筑观察。', '选择一处具有清晰几何秩序的真实建筑空间，让一束自然光定义画面主路径；只保留一位远处人物作为尺度参照。', '避免 HDR 油光、赛博灯带、样板房式商业感和无意义装饰。', ARRAY['建筑', '空间', '自然光'], '/showcase-image-building-preview.webp', 'ComfyUI 创作工作流', 'https://github.com/Comfy-Org/ComfyUI', TRUE, 60),
    ('documentary-still', '纪实电影静帧', 'TEXT_TO_IMAGE', '让电影感来自人物选择和可信环境，而不是重滤镜。', '给人物一个尚未完成的决定和明确动作，选择有天气痕迹的真实空间。明确观众从何处进入画面、被什么停住、最后看向何处。', '颜色只来自服装、灯光、天气和场景材质；不用现有影视 IP、商标或文字。', ARRAY['电影感', '叙事', '纪实'], '/gallery-cinema-harbor-messenger.png', 'Cinema DNA 21:9 x 3', 'https://github.com/dacnay816y62-hub/cinema-dna-21x9x3', TRUE, 70),
    ('character-bible', '角色设定全案', 'TEXT_TO_IMAGE', '用三视图、表情、动作和配色讲完整角色，而非单张头像。', '制作原创角色设计板：完整正侧背三视图、六种情绪表情、四个明确行动姿态，以及材质和配色样本。每个部分都服务同一角色的性格和任务。', '角色、道具、服装和世界观必须独立原创；不要模仿现有动画、漫画、游戏或影视 IP。', ARRAY['角色', '设定板', '原创IP'], '/gallery-character-bible-cloud-lantern.png', 'PixelScribe 原创配方', '', TRUE, 80),
    ('product-editorial-still', '编辑感产品静物', 'TEXT_TO_IMAGE', '用真实材质和方向光完成高级产品主视觉。', '让一件产品成为唯一主角，放在安静的建筑台面上；使用可触摸的材质细节、方向感晨光和克制阴影，为中文标题预留留白。', '不要生成商标、包装文案、假文字或过度光泽。', ARRAY['产品', '静物', '杂志'], '/showcase-image-city-preview.webp', 'GPT Image 2 Skill', 'https://github.com/wuyoscar/GPT-Image2-Skill', TRUE, 90),
    ('hand-drawn-thought', '手绘观点配图', 'TEXT_TO_IMAGE', '以一个荒诞但成立的动作，把文章观点变成简洁插图。', '横版白底手绘解释图：让黑色极简角色完成一个与主题相关的荒诞动作，只选择一个低科技物件作为隐喻，并保留至少三分之一留白。', '黑色线稿为主，红橙蓝只作少量批注；不做 PPT、商业插画或儿童卡通。', ARRAY['文章配图', '手绘', '观点'], '', 'Ian 小黑怪诞正文配图', '', TRUE, 100),
    ('contemporary-eastern-life', '当代东方生活方式', 'TEXT_TO_IMAGE', '以现代空间、自然材质和克制色彩表达东方生活方式。', '选择一件日常器物、一个自然材料和一束真实侧光作为全部视觉元素。空间保持现代、安静和可居住，色彩来自木材、陶土、布料与植物本身。', '避免国潮符号堆砌、伪书法、饱和金红配色、磨皮人像和油亮商业质感。', ARRAY['东方美学', '生活方式', '自然材质'], '/gallery-moments-solar-term.png', '东方美术导演 Skill', 'https://github.com/Litreily/codex-skill-eastern-beauty-director', TRUE, 110),
    ('structured-camera-recipe', '镜头与材质配方', 'TEXT_TO_IMAGE', '用结构化的镜头、光线与负面约束生成可比较的系列画面。', '先明确用途、主体与唯一动作，再依次写清场景、镜头距离、视线方向、真实光源、色彩来源和材质细节。最后用负面约束排除文字、商标、重复主体和无关特效。', '每次只改变一个视觉变量，形成可比较的系列；不要靠大滤镜掩盖构图问题。', ARRAY['镜头', '材质', '系列'], '/gallery-moments-photo-diary.png', 'GPT Image Cookbook', 'https://github.com/eugeniughelbur/gpt-image-cookbook', TRUE, 120),
    ('moments-diptych', '朋友圈双联对照', 'TEXT_TO_IMAGE', '用远景和局部的双联结构记录一个真实场景。', '左侧只呈现有明确空间关系的远景，右侧只呈现同一场景中可触摸的局部细节。两侧共享同一光线、色温和真实时间线。', '使用干净留白作间隔；不加入贴纸、边框文字、商标、强滤镜或无关道具。', ARRAY['朋友圈', '双联', '日常观察'], '/gallery-moments-photo-diary.png', 'GPT Image Cookbook', 'https://github.com/eugeniughelbur/gpt-image-cookbook', TRUE, 130),
    ('moments-nine-grid', '朋友圈九宫格片段', 'TEXT_TO_IMAGE', '用九个不同镜头完成一件小事的完整记录。', '按环境、抵达、局部、人物动作、器物、颜色、转场、安静时刻与收束镜头安排九个画面；所有画面共享相近色温和真实时间线。', '不做拼贴贴纸、假文字、过度磨皮或重复构图。', ARRAY['朋友圈', '九宫格', '叙事'], '/gallery-moments-photo-diary.png', 'GPT Image Cookbook', 'https://github.com/eugeniughelbur/gpt-image-cookbook', TRUE, 140),
    ('method-flow', '实验方法路径', 'SCI_FIG', '将实验步骤、变量、对照与输出做成可复核的方法图。', '用从左至右的一条实验主路径组织画面，只保留必要阶段、对照分支和输出。所有箭头都必须表达变量关系。', '统一线宽，暖白背景，蓝橙配色；不添加装饰性模块或伪数据。', ARRAY['方法图', '实验', '流程'], '/gallery-science-nanocarrier.png', 'Storytelling Figures', '', TRUE, 50),
    ('spatial-atlas', '空间分布图谱', 'SCI_FIG', '把样本位置、差异区域和空间尺度放在同一张图。', '选择一个主空间底图，用不超过三种编码展示样本分布、重点区域和比较对象；为比例尺、图例与低密度标签留出位置。', '色彩只服务分类与差异，不用发光轮廓、伪三维或装饰粒子。', ARRAY['空间组学', '地图', '分布'], '/gallery-science-ecosystem.png', 'napari', 'https://github.com/napari/napari', TRUE, 60),
    ('evidence-comparison', '对照证据页', 'SCI_FIG', '将实验组、对照组和结论以同尺度排布。', '以对齐的实验组和对照组为骨架，用同一尺度展示样本、关键指标与差异位置。每组只保留一个主结果和一条证据线。', '显著性、误差和样本量需有真实位置；不虚构数据，不用装饰图标替代证据。', ARRAY['对照', '结果图', '证据'], '/gallery-science-materials-cutaway.png', 'Matplotlib', 'https://github.com/matplotlib/matplotlib', TRUE, 70),
    ('publication-panels', '出版级多面板图', 'SCI_FIG', '为问题、方法、观察和结论构建可跳读的论文图。', '采用四面板结构，但先定义从问题、方法、观察到结论的阅读顺序。各面板统一边距、线宽、配色和说明密度。', '图像与数据仅用必要引导线连接，预留真实图题与图注区域。', ARRAY['论文图', '多面板', '出版'], '/gallery-science-nanocarrier.png', 'ImageJ 生态', 'https://github.com/imagej/ImageJ', TRUE, 80),
    ('materials-lens', '材料微观透镜', 'SCI_FIG', '用宏观器件、剖面和微观放大构成连续材料叙事。', '从一个宏观器件剖面进入一到两个微观放大窗，清晰展示层间关系、孔隙或颗粒结构与一条核心输运路径。', '保持比例可信和出版级留白，不做科幻 UI、霓虹发光或无关机械零件。', ARRAY['材料', '剖面', '微观'], '/gallery-science-materials-cutaway.png', 'PixelScribe 原创配方', '', TRUE, 90),
    ('urban-ecology', '城市生态连续图', 'SCI_FIG', '用连续地貌和物质流表达环境过程。', '从源头到下游建立连续地貌，以一条水流、能量流或物质流串联关键过程；仅保留必要采样点和两个放大窗。', '所有元素服务因果关系，避免儿童插画、图标堆叠和无意义箭头。', ARRAY['生态', '环境', '过程图'], '/gallery-science-ecosystem.png', 'PixelScribe 原创配方', '', TRUE, 100),
    ('scientific-hero', '科研封面主图', 'SCI_FIG', '在严谨结构之上，做可用于论文首页和报告封面的科学主视觉。', '选择一个核心实体作为主视觉，以明确尺度关系连接微观细节和真实研究场景；保留标题、作者和单位的后期排版安全区。', '不生成假公式、不可读标签、学校标志或夸张的科幻特效。', ARRAY['封面', '科研传播', '主视觉'], '/gallery-science-nanocarrier.png', 'BioIcons', 'https://github.com/bioicons/bioicons', TRUE, 110),
    ('conceptual-graphical-abstract', '概念图形摘要', 'SCI_FIG', '把研究问题、干预、机制和意义压缩为可追踪的概念路径。', '先明确研究对象、干预、核心机制和研究意义，再用一条主路径依次连接它们。只设置必要的一个到两个放大观察窗，并为图注保留位置。', '必须明确为概念示意；不伪造显微图、患者照片、统计图、具体数值或无法核实的因果结论。', ARRAY['图形摘要', '概念示意', '科研诚信'], '/gallery-science-hydrogel-repair.png', 'paper-image-ppt', 'https://github.com/Libby5201234/paper-image-ppt', TRUE, 120),
    ('cultural-program', '文化节目主视觉', 'POSTER_GEN', '用单一视觉物、网格和留白制作展览、演出与公共活动海报。', '选择一件代表主题的物体、身体姿态或空间切片作为唯一主视觉，用不对称网格、两级排版安全区和一枚强调色组织画面。', '避免伪书法、复杂花纹、乱码文字和廉价金属光泽。', ARRAY['文化', '展览', '活动'], '/gallery-poster-swiss-grid.png', 'GPT Image 2 开源提示词图库', 'https://github.com/ChaosRealmsAI/gpt-image-2-gallery', TRUE, 50),
    ('product-editorial-poster', '编辑式产品海报', 'POSTER_GEN', '把新品拍成有观点的杂志封面。', '让产品成为唯一主角，用一个有质感台面和一个克制辅助道具建立叙事；使用方向明确的自然光与大量留白。', '标题和卖点留给后期排版，不生成包装文案、商标或水印。', ARRAY['产品', '新品', '编辑感'], '/gallery-poster-new-chinese-tea.png', 'GPT Image 2 Skill', 'https://github.com/wuyoscar/GPT-Image2-Skill', TRUE, 60),
    ('data-story-poster', '数据叙事海报', 'POSTER_GEN', '把一个核心数字、趋势和行动信息做成可扫描传播页。', '选择一个主数字或主结论作为视觉锚点，用一条趋势、三个以内支持指标和清晰行动区组织阅读。', '图标需统一线宽和比例，正文与数值留后期真实排版位置；不生成假数据。', ARRAY['数据', '信息设计', '传播'], '/gallery-poster-airclean-architecture.jpg', 'Lucide', 'https://github.com/lucide-icons/lucide', TRUE, 70),
    ('editorial-collage', '杂志纸艺拼贴', 'POSTER_GEN', '用真实照片锚点、纸张结构和受控色彩组成轻快传播物。', '保留一个真实摄影锚点，将重复细节压缩为两到三层纸张形状、简化插画和局部手绘标注。', '只使用一块高饱和结构色，保留中文标题安全区；不生成密集文字。', ARRAY['拼贴', '杂志', '纸艺'], '/gallery-poster-citrus-collage.png', 'Gathered Scenes Zine', 'https://github.com/Zeejay0/gathered-scenes-zine-skill', TRUE, 80),
    ('night-event', '夜间活动动线', 'POSTER_GEN', '用灯光、路径和人物方向组织有速度感的活动主视觉。', '让人物或运动轨迹沿一条清晰对角线前进，以真实环境光和一枚强调色建立速度与集合感。', '预留日期、地点与报名信息区，不生成文字、号码、商标或水印。', ARRAY['活动', '运动', '夜景'], '/gallery-poster-night-run.png', 'PixelScribe 原创配方', '', TRUE, 90),
    ('new-chinese-product', '新中式产品叙事', 'POSTER_GEN', '用实物与单一东方意象建立克制商业视觉。', '让真实产品成为主体，用山形、器物、花枝或月色中的一个意象建立前后层次；色彩只来自实物、自然光和材质。', '避免符号堆砌、金色滥用、传统元素大杂烩和伪书法。', ARRAY['新中式', '品牌', '留白'], '/gallery-poster-new-chinese-tea.png', 'PixelScribe 原创配方', '', TRUE, 100),
    ('icon-system-poster', '图标系统海报', 'POSTER_GEN', '用统一图标和功能块呈现产品能力或公共服务信息。', '先定义统一笔画和比例的一组图标，再用五个以内功能区块建立阅读顺序。控制为两种主色并保留真实信息区。', '不拼贴库存照片，不生成商标、复杂小字或不一致图标。', ARRAY['图标', '信息图', '产品'], '/showcase-poster-airclean-architecture.jpg', 'OpenMoji / Lucide', 'https://github.com/lucide-icons/lucide', TRUE, 110),
    ('ad-key-visual-system', '广告关键视觉系统', 'POSTER_GEN', '用一个强主角、一项视觉承诺和清晰安全区完成投放级主视觉。', '先定义受众、唯一主角、核心承诺和投放位置，再选一个可被一眼识别的场景动作。主角与背景保持明确层级，标题、价格和行动信息仅预留后期安全区。', '避免包装文案、商标、水印、过多道具和无法阅读的小字。', ARRAY['广告', '关键视觉', '投放'], '/gallery-poster-citrus-collage.png', 'AI 广告提示词指南', 'https://github.com/creatify-ai/ai-ad-prompt-guide', TRUE, 120)
ON CONFLICT (id) DO NOTHING;
